findings.existing_code:
source: {type: string, enum: [coordinator, local-static]}
        policy_version: {type: string}
        policy_checksum: {type: string, pattern: '^[a-f0-9]{64}$'}
        matched_rule_ids: {type: array, items: {type: string}}
        rationale: {type: array, items: {type: string}}
        persisted: {type: boolean}
        durable_audit: {type: boolean}

task_signals:
          type: object
          required: [archetype]
          properties:
            archetype: {type: string, minLength: 1}
            phase: {type: [string, "null"], default: null}
            task_type: {type: [string, "null"], default: null}
            complexity: {type: [string, "null"], enum: [low, medium, high, null]}
            modality: {type: string, enum: [interactive, programmatic], default: programmatic}
          additionalProperties: true
